  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is healthcare robotics data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of demonstrations and sensor data that train robots for hospitals, clinics, labs, and care homes, such as supply delivery, fetching items, assisting people, and handling clinical objects, with patient privacy designed into how data is captured."
        }
      },
      {
        "@type": "Question",
        "name": "How do you protect patient privacy during data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We design capture so patient information isn't recorded in the first place: mock rooms, off-hours sessions, consented participants only, and on-device blurring of faces, screens, and documents. Programs are planned with your compliance team from the start."
        }
      },
      {
        "@type": "Question",
        "name": "Do you collect data with real patients?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Human-interaction data is recorded with trained actors and mannequins in mock clinical rooms, not with patients as test subjects. Any work in live facilities follows the facility's own approval and consent processes."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data inside a working hospital?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, when the facility approves it. We schedule around clinical workflows, use equipment that meets infection-control requirements, and keep patients out of frame unless consent is documented."
        }
      },
      {
        "@type": "Question",
        "name": "Which robots do you collect healthcare data for?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Hospital logistics and delivery robots, mobile manipulators that fetch items for staff, eldercare and assistive robots, disinfection robots, and lab automation systems."
        }
      },
      {
        "@type": "Question",
        "name": "How does healthcare data differ from general robot data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Clinical spaces bring privacy constraints, dense clutter, reflective and transparent materials, human contact, and round-the-clock variation. Open datasets rarely include these conditions, so teams need data from real or realistic clinical environments."
        }
      }
    ]
  }
]
